CREATE TABLE IF NOT EXISTS users (
id INTEGER PRIMARY KEY AUTOINCREMENT, name VARCHAR(100) NOT NULL, email VARCHAR(120) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL,
role VARCHAR(20) NOT NULL CHECK(role IN ('cliente','vendedor','administrador')), active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)), created_at DATETIME NOT NULL
);
CREATE TABLE IF NOT EXISTS products (
id INTEGER PRIMARY KEY AUTOINCREMENT, seller_id INTEGER NOT NULL, name VARCHAR(150) NOT NULL, material TEXT NOT NULL, utility TEXT NOT NULL, history TEXT NOT NULL,
municipality VARCHAR(100) NOT NULL, category VARCHAR(30) NOT NULL CHECK(category IN ('textiles','ceramica','madera','decoracion')), price DECIMAL(10,2) NOT NULL CHECK(price>0), stock INT NOT NULL DEFAULT 0 CHECK(stock>=0), source TEXT NOT NULL, published INTEGER NOT NULL DEFAULT 1 CHECK(published IN(0,1)), image VARCHAR(255) NOT NULL, illustrative INTEGER NOT NULL DEFAULT 0, version INT NOT NULL DEFAULT 1, created_at DATETIME NOT NULL,
FOREIGN KEY(seller_id) REFERENCES users(id)
);
CREATE TABLE IF NOT EXISTS orders (
id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,total DECIMAL(10,2) NOT NULL CHECK(total>0),status VARCHAR(30) NOT NULL DEFAULT 'pendiente',operation_key CHAR(64) NOT NULL UNIQUE,created_at DATETIME NOT NULL,
FOREIGN KEY(user_id) REFERENCES users(id)
);
CREATE TABLE IF NOT EXISTS order_items (
id INTEGER PRIMARY KEY AUTOINCREMENT,order_id INTEGER NOT NULL,product_id INTEGER NOT NULL,product_name VARCHAR(150) NOT NULL,quantity INT NOT NULL CHECK(quantity>0),unit_price DECIMAL(10,2) NOT NULL,subtotal DECIMAL(10,2) NOT NULL,
FOREIGN KEY(order_id) REFERENCES orders(id),FOREIGN KEY(product_id) REFERENCES products(id)
);
CREATE TABLE IF NOT EXISTS login_attempts (attempt_key CHAR(64) PRIMARY KEY,attempts INT NOT NULL,window_start INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS audit_log (id INTEGER PRIMARY KEY AUTOINCREMENT,actor_id INTEGER NOT NULL,action VARCHAR(50) NOT NULL,subject_id INTEGER NOT NULL,created_at DATETIME NOT NULL,FOREIGN KEY(actor_id) REFERENCES users(id));
